import type OpenFin from '@openfin/core';

export type FindInPageChannelMessagePayload =
    | { type: 'close' }
    | { type: 'find-text-changed'; value: string }
    | { type: 'focus-input' }
    | { type: 'hide-from-search-menu' }
    | { type: 'next-result' }
    | { type: 'previous-result' }
    | { type: 'show' }
    | { type: 'update-state'; currentResultIndex?: number | null; totalResults?: number | null; value?: string | null }
    | { type: 'view-ready' }
    | { type: 'window-ready' };

/**
 * Closes the find in page channel
 */
export const closeFindInPageChannel = (channel: BroadcastChannel) => {
    channel.close();
};

/**
 * Gets the name of the find in page channel for the current window.
 *
 * @returns The name of the find in page channel.
 */
const getFindInPageChannelName = async (channelNamePostfix?: string): Promise<string> => {
    const channelNamePrefix = 'find-in-page';
    let channelName: string;
    if (channelNamePostfix) {
        channelName = `${channelNamePrefix}-${channelNamePostfix}`;
    } else {
        const currentWindow = await (fin.me.isWindow
            ? (fin.me as OpenFin.Window)
            : (fin.me as OpenFin.View).getCurrentWindow());
        channelName = `${channelNamePrefix}-${currentWindow.identity.name}`;
    }
    return channelName;
};

/**
 * Creates a new find in page channel
 */
export const createFindInPageChannel = async (windowName?: string) => {
    const channelName = await getFindInPageChannelName(windowName);
    return new BroadcastChannel(channelName);
};

/**
 * Sends a message via the find in page channel
 */
export const sendFindInPageMessage = (channel: BroadcastChannel, message: FindInPageChannelMessagePayload) => {
    channel.postMessage(message);
};
